package com.rohit.inventory.controller;
import com.rohit.inventory.dto.response.*; import com.rohit.inventory.service.RoleService; import java.util.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/roles") public class RoleController { private final RoleService service; public RoleController(RoleService service){this.service=service;} @GetMapping @PreAuthorize("hasAuthority('ROLE_READ')") public ApiResponse<List<RoleResponse>> list(){return ApiResponse.success("Roles retrieved successfully",service.list());} @GetMapping("/{id}") @PreAuthorize("hasAuthority('ROLE_READ')") public ApiResponse<RoleResponse> get(@PathVariable UUID id){return ApiResponse.success("Role retrieved successfully",service.get(id));} }
